				udc_obj.getValue_1 = function(){

				};

				/**
				 * Function description...
				 * @date 2019. 06. 20
				 * @memberOf udc_obj
				 * @param 
				 * @returns  
				 * @author mo
				 * @example
				 * @since
				*/ 
				udc_obj.onTrigger1 = function(){
				    console.log("udc_obj.onTrigger1");
                    var udcID = udc_obj.id;

                    //엔진패치 전 20181217 버전에서 되던 동작?
                    //아래 방식은 버전과 상관없이 scope=""일 때 동작 scope="true"일 때는 동작안함.
                    var funcStr = $p.parent().$p.id + "scwin.outter_wframe";
                    var func = eval(funcStr);
                    if(typeof func === "function") {
                        func(udcID);
                    } else {
                        alert(funcStr + " is not a function");
                    }
				};

				/**
				 * Function description...
				 * @date 2019. 06. 20
				 * @memberOf udc_obj
				 * @param 
				 * @returns  
				 * @author mo
				 * @example
				 * @since
				*/ 
				udc_obj.onTrigger2 = function(){
				    console.log("udc_obj.onTrigger2");
                    debugger;
                    var udcID = udc_obj.id;

                    //엔진패치 후 20190614 버전에서 되는 동작?
                    //아래 방식은 버전 및 scope과 상관없이 잘 동작함.

                    var _win = window || parent;

                    var funcStr = "scwin.outter_wframe";
                    var objArr = funcStr.split(".");

                    var callbackFn = _win[objArr[0]][objArr[1]];
                    callbackFn(udcID);
				};
